{{
  config(
    materialized = 'incremental',
    unique_key   = 'event_id',
    partition_by = {'field': 'loaded_date', 'data_type': 'date'},
    on_schema_change = 'sync_all_columns'
  )
}}

/*
  Raw 레이어: 소스 미러링 (1:1 반영)
  비즈니스 로직 없음 — 타입 캐스팅 및 컬럼명 정리만 수행
  _raw JSON 은 파싱하지 않고 원본 보존

  원본: raw_labelit_workspace_command (Zerobus → MongoDB → Delta Table)
*/

SELECT
  _id                           AS event_id,
  _raw,
  to_timestamp(occurred_at)     AS occurred_at,
  DATE(to_timestamp(occurred_at)) AS loaded_date

FROM {{ source('labelit_raw', 'raw_labelit_workspace_command') }}

{% if is_incremental() %}
  WHERE to_timestamp(occurred_at) > (SELECT MAX(occurred_at) FROM {{ this }})
{% endif %}
